//! Implementation of Python's `dataclasses` module.
//!
//! Native, in-sandbox `@dataclass`: the decorator writes a `__dataclass_fields__`
//! mapping of [`DataclassField`]s into the class namespace, then the dunders
//! CPython would generate, each a [`DataclassMethod`] holding a snapshot of the
//! decoration — no `exec`, no generated bytecode. The VM's construction and
//! value-dunder paths call those methods' native code directly (see `method`).
//!
//! See `limitations/dataclasses.md` for divergences from CPython.

mod field;
mod legacy;
mod method;
mod options;

pub(crate) use self::{
    field::DataclassField,
    legacy::{LEGACY_DUMP_VERSION, upgrade_legacy_classes},
    method::{
        DataclassMethod, dataclass_eq, dataclass_hash, dataclass_repr_fmt, frozen_assignment_error, generated_fields,
        is_generated_init, run_init,
    },
    options::{DataclassOptions, DataclassParams},
};
use self::{
    field::{adoptable_field, field_at_id},
    method::{FieldInit, MethodKind},
};
use crate::{
    args::{ArgValues, FromArgs},
    builtins::Builtins,
    bytecode::VM,
    defer_drop,
    exception_private::{ExcType, ExcTypeExt, RunError, RunResult, SimpleException},
    heap::{DropGuard, DropWithContext, Heap, HeapData, HeapId, HeapRead, HeapReadMut, HeapReadOutput, HeapReader},
    intern::{Interns, StaticStrings, StringId},
    modules::ModuleFunctions,
    types::{
        Class, Dict, Module, PyTrait, TupleVec, allocate_tuple,
        host_class::host_class_type,
        instance::{class_defines, namespace_member},
    },
    value::{Marker, Value},
};

/// `dataclasses` module functions — each variant is a Python-visible callable.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, strum::Display, serde::Serialize, serde::Deserialize)]
#[strum(serialize_all = "snake_case")]
pub(crate) enum DataclassesFunctions {
    /// The `@dataclass` decorator.
    Dataclass,
    /// `is_dataclass(obj)` — true for a dataclass class or instance.
    IsDataclass,
    /// `field(...)` — builds the `Field` a class body binds and the decorator
    /// then adopts.
    Field,
    /// The decorator `@dataclass(...)` returns while it waits for the class,
    /// carrying the bound options so `d = dataclass(frozen=True)` then `@d`
    /// works. Named for the user-visible decorator, not the variant.
    #[strum(serialize = "dataclass")]
    Configured(DataclassOptions),
}

/// Creates the `dataclasses` module and allocates it on the heap.
pub fn create_module(vm: &mut VM<'_>) -> HeapId {
    let mut module = Module::new(StaticStrings::Dataclasses, vm.interns);
    module.set_attr(
        StaticStrings::Dataclass,
        Value::ModuleFunction(ModuleFunctions::Dataclasses(DataclassesFunctions::Dataclass)),
        vm,
    );
    module.set_attr(
        StaticStrings::IsDataclass,
        Value::ModuleFunction(ModuleFunctions::Dataclasses(DataclassesFunctions::IsDataclass)),
        vm,
    );
    module.set_attr(
        StaticStrings::FrozenInstanceError,
        Value::Builtin(Builtins::ExcType(ExcType::FrozenInstanceError)),
        vm,
    );
    module.set_attr(
        StaticStrings::Field,
        Value::ModuleFunction(ModuleFunctions::Dataclasses(DataclassesFunctions::Field)),
        vm,
    );
    // `MISSING` is a bare sentinel compared by identity, so it needs no state
    // beyond its name — a `Marker` like `sys.stdout`, with a type of its own.
    module.set_attr(
        StaticStrings::Missing,
        Value::Marker(Marker(StaticStrings::Missing)),
        vm,
    );
    vm.heap.allocate_as(module).into_id()
}

/// Dispatches a `dataclasses` module function call.
pub(super) fn call(vm: &mut VM<'_>, func: DataclassesFunctions, args: ArgValues) -> RunResult<Value> {
    match func {
        DataclassesFunctions::Dataclass => dataclass_decorator(vm, args),
        DataclassesFunctions::IsDataclass => is_dataclass(vm, args),
        DataclassesFunctions::Field => field::field(vm, args),
        // The options are already bound; this call supplies the class.
        DataclassesFunctions::Configured(options) => {
            let ConfiguredArgs { cls } = ConfiguredArgs::from_args(args, vm)?;
            apply_dataclass(vm, cls, options)
        }
    }
}

/// The `@dataclass` decorator, in both spellings: applied bare the class
/// arrives here directly, while `@dataclass(...)` has none yet and gets back a
/// [`DataclassesFunctions::Configured`] that receives it on the next call.
fn dataclass_decorator(vm: &mut VM<'_>, args: ArgValues) -> RunResult<Value> {
    let DataclassArgs {
        cls,
        init,
        repr,
        eq,
        order,
        unsafe_hash,
        frozen,
        match_args,
        kw_only,
        slots,
        weakref_slot,
    } = DataclassArgs::from_args(args, vm)?;
    // CPython's `dataclass` is a `def`, so it type-checks nothing and takes each
    // option's truthiness. That runs user code — a `__bool__` may raise — so
    // `cls` and all ten flags are guarded before the first read.
    let mut guard = DropGuard::new(
        [
            cls,
            init,
            repr,
            eq,
            order,
            unsafe_hash,
            frozen,
            match_args,
            kw_only,
            slots,
            weakref_slot,
        ],
        vm,
    );
    let (values, vm) = guard.as_parts();
    let mut truthy = [false; 10];
    for (slot, flag) in truthy.iter_mut().zip(&values[1..]) {
        *slot = flag.py_bool(vm)?;
    }
    let [
        init,
        repr,
        eq,
        order,
        unsafe_hash,
        frozen,
        match_args,
        kw_only,
        slots,
        weakref_slot,
    ] = truthy;
    let options = DataclassOptions { eq, frozen };
    // Options Monty does not implement are refused when set away from their
    // CPython default, rather than accepted and ignored.
    let unimplemented = [
        ("init", init, true),
        ("repr", repr, true),
        ("order", order, false),
        ("unsafe_hash", unsafe_hash, false),
        ("match_args", match_args, true),
        ("kw_only", kw_only, false),
        ("slots", slots, false),
        ("weakref_slot", weakref_slot, false),
    ]
    .into_iter()
    .find(|&(_, given, default)| given != default);
    // Only truthiness is kept, so the flags are released here; `cls` alone lives
    // on, into the return value.
    let (values, vm) = guard.into_parts();
    let [cls, flags @ ..] = values;
    flags.drop_with(vm);
    match unimplemented {
        Some((name, _, _)) => {
            cls.drop_with(vm);
            Err(ExcType::not_implemented(format!("dataclass() does not yet support the {name} option")).into())
        }
        // `@dataclass(...)`: no class yet, so hand back the configured decorator.
        None if matches!(cls, Value::None) => Ok(Value::ModuleFunction(ModuleFunctions::Dataclasses(
            DataclassesFunctions::Configured(options),
        ))),
        None => apply_dataclass(vm, cls, options),
    }
}

/// `@dataclass` arguments, mirroring CPython's
/// `dataclass(cls=None, /, *, init=True, repr=True, ...)`.
///
/// Raw `Value` fields because CPython's `def` type-checks nothing; the body
/// takes each option's truthiness instead.
#[derive(FromArgs)]
#[from_args(name = "dataclass", style = def)]
struct DataclassArgs {
    #[from_args(pos_only, default = Value::None)]
    cls: Value,
    #[from_args(kw_only, default = Value::Bool(true))]
    init: Value,
    #[from_args(kw_only, default = Value::Bool(true))]
    repr: Value,
    #[from_args(kw_only, default = Value::Bool(true))]
    eq: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    order: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    unsafe_hash: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    frozen: Value,
    #[from_args(kw_only, default = Value::Bool(true))]
    match_args: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    kw_only: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    slots: Value,
    #[from_args(kw_only, default = Value::Bool(false))]
    weakref_slot: Value,
}

/// The class a [`DataclassesFunctions::Configured`] decorator is waiting for.
///
/// CPython's `dataclass` closes over a plain `def wrap(cls)`, so the class binds
/// positionally *or* by keyword, and the arity errors name that closure rather
/// than `dataclass` itself. Raw `Value` for [`DataclassArgs`]' reason: a `def`
/// type-checks nothing, and `apply_dataclass` makes the class check the body
/// would.
#[derive(FromArgs)]
#[from_args(name = "dataclass.<locals>.wrap", style = def)]
struct ConfiguredArgs {
    cls: Value,
}

/// Writes `__dataclass_fields__`, `__dataclass_params__` and the generated
/// dunders into the class namespace, and returns the class itself.
///
/// Ownership of `cls` passes straight through to the return value, so no extra
/// refcount work is needed on the happy path; the guard releases it on every
/// path that rejects the class instead.
fn apply_dataclass(vm: &mut VM<'_>, cls: Value, options: DataclassOptions) -> RunResult<Value> {
    let mut guard = DropGuard::new(cls, vm);
    let (cls, vm) = guard.as_parts();
    // Read once and pass the handle down: everything below then works from a
    // value already known to be a class, and the guard's reference keeps it alive.
    let Value::Ref(class_id) = cls else {
        return Err(non_class_error(cls, vm));
    };
    let HeapReadOutput::Class(class) = vm.heap.read(*class_id) else {
        return Err(non_class_error(cls, vm));
    };
    let fields = build_dataclass_fields(&class, vm)?;
    let Value::Ref(fields_id) = fields else {
        unreachable!("the fields mapping is a dict")
    };
    // Fields first, so nothing owns the mapping while the params allocation
    // can still fail; a class left with fields alone acts as a default one.
    store_dataclass_fields(&class, fields, vm)?;
    // Now that the mapping owns them, the `field()` objects the class body left
    // as attributes can be rewritten to what CPython leaves behind.
    rewrite_field_attributes(&class, fields_id, vm)?;
    store_dataclass_params(&class, options, vm)?;
    install_generated_methods(*class_id, &class, fields_id, options, &mut Installer::Decorate(vm))?;
    store_match_args(&class, fields_id, vm)?;
    Ok(guard.into_inner())
}

/// `dataclass()` applied to something that is not a class.
fn non_class_error(cls: &Value, vm: &VM<'_>) -> RunError {
    let type_name = cls.py_type_name(vm);
    SimpleException::new_msg(
        ExcType::TypeError,
        format!("dataclass() should be called on a class, not '{type_name}'"),
    )
    .into()
}

/// Builds the `name -> Field` mapping for `class` from its `__annotations__`:
/// the annotated names in definition order, minus `ClassVar` entries, each
/// owning the default the class namespace bound for it (`y: int = 5`).
///
/// Also where a class body Monty cannot yet honour is rejected, so an
/// unimplemented feature raises rather than producing a subtly wrong class
/// (see `limitations/dataclasses.md`). The fields are guarded throughout, so a
/// rejection releases the defaults already captured.
fn build_dataclass_fields<'h>(class: &HeapRead<'h, Class>, vm: &mut VM<'h>) -> RunResult<Value> {
    let fields = collect_annotated_fields(class, vm);
    let mut guard = DropGuard::new(fields, vm);
    let (fields, vm) = guard.as_parts();
    // Field validation runs first, so a class CPython would reject reports
    // CPython's own message and the Monty-only guards can only fire after.
    validate_fields(vm, fields)?;
    let (fields, vm) = guard.into_parts();
    allocate_fields_dict(vm, fields)
}

/// Allocates the dict `__dataclass_fields__` holds, consuming the collected
/// fields. The dict owns every `Field` from its first insertion, so a failure
/// part-way releases them with it.
fn allocate_fields_dict(vm: &mut VM<'_>, fields: Vec<Value>) -> RunResult<Value> {
    let dict = vm.heap.allocate_as(Dict::with_capacity(fields.len()));
    let mut guard = DropGuard::new(dict, vm);
    let (dict, vm) = guard.as_parts_mut();
    let dict = dict.read(vm.heap);
    for field_value in fields {
        // Consumed rather than matched: the reference moves into the dict below,
        // so the original must not also be released.
        let Some(field_id) = field_value.into_ref_id() else {
            unreachable!("collection produces only heap fields")
        };
        let name = field_at_id(vm.heap, field_id)
            .expect("collection produces only `Field`s")
            .name()
            .expect("collection adopts every field");
        // One `field()` object bound under two names is adopted twice and keyed
        // by the second, so a replacement does happen — CPython collapses the
        // pair the same way. A dict rejected by the memory limit releases the
        // field it was handed.
        let replaced = dict.set(Value::InternString(name), Value::Ref(field_id), vm)?;
        replaced.drop_with(vm);
    }
    Ok(guard.into_inner().into_value())
}

/// Writes `__dataclass_fields__` into the class namespace, taking ownership of
/// `fields`. Re-decorating replaces the previous mapping, which nothing else
/// owns once it is out of the namespace.
fn store_dataclass_fields<'h>(class: &HeapReadMut<'h, Class>, fields: Value, vm: &mut VM<'h>) -> RunResult<()> {
    let name = Value::InternString(vm.interns.intern_static(StaticStrings::DataclassFields));
    let replaced = class.set_attr(name, fields, vm)?;
    replaced.drop_with(vm);
    Ok(())
}

/// Writes `__dataclass_params__` into the class namespace, as CPython's
/// `_DataclassParams` records the same options.
///
/// A record only: the generated methods carry their own copy of what they
/// need, so rebinding this entry changes nothing, as in CPython.
fn store_dataclass_params<'h>(
    class: &HeapReadMut<'h, Class>,
    options: DataclassOptions,
    vm: &mut VM<'h>,
) -> RunResult<()> {
    let params = vm.heap.allocate_as(DataclassParams::new(options)).into_value();
    let name = Value::InternString(vm.interns.intern_static(StaticStrings::DataclassParams));
    let replaced = class.set_attr(name, params, vm)?;
    replaced.drop_with(vm);
    Ok(())
}

/// Writes `__match_args__` into the class namespace: the field names in
/// definition order, so `case Point(x, y):` binds positionally. A class that
/// defines its own `__match_args__` keeps it, as in CPython.
fn store_match_args<'h>(class: &HeapReadMut<'h, Class>, fields_id: HeapId, vm: &mut VM<'h>) -> RunResult<()> {
    let name_id = vm.interns.intern_static(StaticStrings::MatchArgsDunder);
    let namespace = class.get(vm.heap).namespace();
    if namespace.get_by_str("__match_args__", vm.heap, vm.interns).is_some() {
        return Ok(());
    }
    let names: TupleVec = adopted_field_ids(fields_id, vm.heap)
        .into_iter()
        .map(|(name, _)| Value::InternString(name))
        .collect();
    let match_args = allocate_tuple(names, vm.heap);
    let replaced = class.set_attr(Value::InternString(name_id), match_args, vm)?;
    replaced.drop_with(vm);
    Ok(())
}

/// Writes the dunders CPython's `_process_class` generates, each a
/// [`DataclassMethod`] built from the fields just stored.
///
/// `__init__`, `__repr__` and `__eq__` are only added when the class body did
/// not define them. Frozen classes refuse a body `__setattr__`/`__delattr__`
/// with CPython's `TypeError`. `__hash__` follows CPython's `_hash_action`
/// table and overwrites whatever the body left, as CPython assigns it outright.
/// [`Installer::Upgrade`] changes three of those choices; see its docs.
fn install_generated_methods<'h>(
    class_id: HeapId,
    class: &HeapReadMut<'h, Class>,
    fields_id: HeapId,
    options: DataclassOptions,
    installer: &mut Installer<'_, 'h>,
) -> RunResult<()> {
    let class_name = class
        .get(installer.heap())
        .name()
        .as_str(installer.interns())
        .to_owned();
    let names: Vec<StringId> = adopted_field_ids(fields_id, installer.heap())
        .into_iter()
        .map(|(name, _)| name)
        .collect();
    // Read before anything is added: CPython's `has_explicit_hash` sees the body
    // alone. A `__hash__ = None` beside a body `__eq__` is the opt-out `type`
    // inserted, not one the author wrote, so a generated hash replaces it.
    let explicit_hash = installer
        .member(class_id, "__hash__")
        .is_some_and(|hash| !(matches!(hash, Value::None) && installer.defines(class_id, "__eq__")));
    let post_init = installer.is_decorating() && installer.defines(class_id, "__post_init__");

    if !installer.defines(class_id, "__init__") {
        let init = DataclassMethod::init(
            class_name.clone(),
            init_fields(fields_id, installer.heap()),
            post_init,
            options.frozen,
        );
        installer.set_method(class, init)?;
    }
    if !installer.defines(class_id, "__repr__") {
        let repr = DataclassMethod::new(class_name.clone(), MethodKind::Repr(names.clone()));
        installer.set_method(class, repr)?;
    }
    if options.eq && !installer.defines(class_id, "__eq__") {
        let eq = DataclassMethod::new(class_name.clone(), MethodKind::Eq(names.clone()));
        installer.set_method(class, eq)?;
    }
    if options.frozen {
        for kind in [MethodKind::FrozenSetattr, MethodKind::FrozenDelattr] {
            let dunder: &'static str = kind.dunder().into();
            if installer.is_decorating() && installer.defines(class_id, dunder) {
                return Err(ExcType::type_error(format!(
                    "Cannot overwrite attribute {dunder} in class {class_name}"
                )));
            }
            installer.set_method(class, DataclassMethod::new(class_name.clone(), kind))?;
        }
    }
    // CPython's `_hash_action` rows for `unsafe_hash=False`, which Monty requires.
    match (options.eq, options.frozen, explicit_hash) {
        (true, true, false) => {
            let hash = DataclassMethod::new(class_name, MethodKind::Hash(names));
            installer.set_method(class, hash)
        }
        (true, false, false) => installer.set_member(class, StaticStrings::DunderHash, Value::None),
        _ => Ok(()),
    }
}

/// Each field's `__init__` parameter: its name and the default or factory
/// captured at decoration, as owned references for the method to hold.
fn init_fields(fields_id: HeapId, heap: &Heap) -> Vec<(StringId, FieldInit)> {
    adopted_field_ids(fields_id, heap)
        .into_iter()
        .map(|(name, field_id)| {
            let field = field_at_id(heap, field_id).expect("adopted ids name fields");
            let init = match (field.default(), field.default_factory()) {
                (Some(default), _) => FieldInit::Default(default.clone_with_heap(heap)),
                (None, Some(factory)) => FieldInit::Factory(factory.clone_with_heap(heap)),
                (None, None) => FieldInit::Unsupplied,
            };
            (name, init)
        })
        .collect()
}

/// Who is installing the generated methods, holding what each needs to write.
enum Installer<'a, 'h> {
    /// `@dataclass` itself, as CPython's `_process_class` would.
    Decorate(&'a mut VM<'h>),
    /// A dataclass from a version 13 dump (see `legacy`), upgraded inside
    /// `Dump::load` before any VM exists. The 1.x rules win: no `__post_init__`
    /// is called (1.x refused one in the body, and never ran one attached later),
    /// a body `__setattr__`/`__delattr__` is replaced rather than refused (1.x
    /// kept the class frozen regardless), and no write can fail.
    Upgrade {
        heap: &'a mut HeapReader<'h>,
        interns: &'a Interns,
    },
}

impl<'h> Installer<'_, 'h> {
    fn heap(&self) -> &HeapReader<'h> {
        match self {
            Self::Decorate(vm) => vm.heap,
            Self::Upgrade { heap, .. } => heap,
        }
    }

    fn interns(&self) -> &Interns {
        match self {
            Self::Decorate(vm) => vm.interns,
            Self::Upgrade { interns, .. } => interns,
        }
    }

    fn is_decorating(&self) -> bool {
        matches!(self, Self::Decorate(_))
    }

    /// Borrows `name` from the class's own namespace.
    fn member(&self, class_id: HeapId, name: &str) -> Option<&Value> {
        namespace_member(class_id, name, self.heap(), self.interns())
    }

    /// Whether the class's own namespace defines `name`.
    fn defines(&self, class_id: HeapId, name: &str) -> bool {
        self.member(class_id, name).is_some()
    }

    /// Allocates `method` and stores it in the class namespace under its dunder.
    fn set_method(&mut self, class: &HeapReadMut<'h, Class>, method: DataclassMethod) -> RunResult<()> {
        let dunder = method.dunder();
        let method = self.heap().allocate_as(method).into_value();
        self.set_member(class, dunder, method)
    }

    /// Stores `value` in the class namespace under `name`, releasing what it
    /// replaces. Only the decorator's write can fail, on its memory preflight;
    /// an upgrade adds at most six entries to a class and skips it.
    fn set_member(&mut self, class: &HeapReadMut<'h, Class>, name: StaticStrings, value: Value) -> RunResult<()> {
        match self {
            Self::Decorate(vm) => {
                let name = Value::InternString(vm.interns.intern_static(name));
                let replaced = class.set_attr(name, value, vm)?;
                replaced.drop_with(&mut **vm);
            }
            Self::Upgrade { heap, interns } => {
                let replaced = class.set_interned_attr(interns.intern_static(name), value, heap, interns);
                replaced.drop_with(&mut **heap);
            }
        }
        Ok(())
    }
}

/// Rewrites the class attribute each `field()` left behind, as CPython does:
/// a plain default becomes the attribute, and a field with only a factory —
/// which has no single value to expose — loses it.
///
/// Runs once the fields are stored, so the mapping is the list of names to fix.
fn rewrite_field_attributes<'h>(class: &HeapReadMut<'h, Class>, fields_id: HeapId, vm: &mut VM<'h>) -> RunResult<()> {
    for (name, field_id) in adopted_field_ids(fields_id, vm.heap) {
        // Only an attribute that *is* the field object needs rewriting; a plain
        // `x: int = 5` already binds the value CPython would leave behind.
        let bound = class
            .get(vm.heap)
            .namespace()
            .get_by_str(vm.interns.get_str(name), vm.heap, vm.interns);
        if !matches!(bound, Some(Value::Ref(id)) if *id == field_id) {
            continue;
        }
        let default =
            field_at_id(vm.heap, field_id).and_then(|field| field.default().map(|v| v.clone_with_heap(vm.heap)));
        let name = Value::InternString(name);
        let replaced = match default {
            Some(default) => class.set_attr(name, default, vm)?,
            None => class.pop_attr(&name, vm)?,
        };
        replaced.drop_with(vm);
    }
    Ok(())
}

/// The `(name, field_id)` of every field in a `__dataclass_fields__` dict.
///
/// The name is the mapping **key**, not the live `Field.name`: adoption writes
/// the name into the `field()` object itself, so one object shared by two
/// classes ends up reporting the *second* class's name.
fn adopted_field_ids(fields_id: HeapId, heap: &Heap) -> Vec<(StringId, HeapId)> {
    let HeapData::Dict(fields) = heap.get(fields_id) else {
        return Vec::new();
    };
    fields
        .iter()
        .filter_map(|(key, value)| match (key, value) {
            (Value::InternString(name), Value::Ref(id)) if field_at_id(heap, *id).is_some() => Some((*name, *id)),
            _ => None,
        })
        .collect()
}

/// Collects the dataclass fields from `__annotations__`, in definition order,
/// dropping `ClassVar` entries, as owned references to heap `Field`s.
///
/// A class-body value that is already a `field()` result is **adopted in place**
/// — the same object gains the name and annotation and goes on to
/// `__dataclass_fields__`, as CPython's decorator does — so
/// `C.__dataclass_fields__['x'] is f`. Anything else is an ordinary default and
/// gets a fresh `Field` built around it.
///
/// The returned references are owned, so a caller that discards them must
/// release them (`drop_with`).
fn collect_annotated_fields<'h>(class: &HeapRead<'h, Class>, vm: &mut VM<'h>) -> Vec<Value> {
    let names = annotated_field_names(class, vm);
    let mut guard = DropGuard::new(Vec::with_capacity(names.len()), vm);
    let (fields, vm) = guard.as_parts_mut();
    for name_id in names {
        let namespace = class.get(vm.heap).namespace();
        // Captured now, as CPython bakes it into the generated `__init__`:
        // rebinding the class attribute later must not change it.
        let bound = namespace
            .get_by_str(vm.interns.get_str(name_id), vm.heap, vm.interns)
            .map(|v| v.clone_with_heap(vm.heap));
        let annotation = field_annotation(class, name_id, vm);
        // The class body bound a `field()` result: it *is* the field, so it
        // takes the name and annotation and the list keeps that reference.
        // Anything else is a plain default, wrapped in a field of its own.
        if let Some(field_id) = adoptable_field(bound.as_ref(), vm) {
            let HeapReadOutput::DataclassField(field) = vm.heap.read(field_id) else {
                unreachable!("adoptable_field matched the variant")
            };
            let replaced = field.get_mut(vm.heap).adopt(name_id, annotation);
            replaced.drop_with(vm);
            fields.push(bound.expect("adoptable_field matched a bound value"));
        } else {
            let field = DataclassField::new(name_id, annotation, bound);
            fields.push(vm.heap.allocate_as(field).into_value());
        }
    }
    guard.into_parts().0
}

/// The annotated field names in definition order, minus `ClassVar` entries.
///
/// Names alone, so the collection loop can take the heap mutably instead of
/// holding a borrow of the annotations dict across an allocation.
fn annotated_field_names<'h>(class: &HeapRead<'h, Class>, vm: &VM<'h>) -> Vec<StringId> {
    let Some(annotations) = annotations_dict(class, vm) else {
        return Vec::new();
    };
    annotations
        .into_iter()
        .filter_map(|(key, annotation)| match key {
            Value::InternString(name_id) if !is_classvar(&annotation_text(annotation, vm)) => Some(*name_id),
            _ => None,
        })
        .collect()
}

/// One field's annotation, cloned as an owned reference for the `Field` to hold.
fn field_annotation<'h>(class: &HeapRead<'h, Class>, name: StringId, vm: &VM<'h>) -> Value {
    annotations_dict(class, vm)
        .and_then(|annotations| annotations.get_by_str(vm.interns.get_str(name), vm.heap, vm.interns))
        .map_or(Value::None, |annotation| annotation.clone_with_heap(vm.heap))
}

/// The class's `__annotations__` dict, or `None` for a class body with none.
fn annotations_dict<'a, 'h>(class: &HeapRead<'h, Class>, vm: &'a VM<'h>) -> Option<&'a Dict> {
    match class
        .get(vm.heap)
        .namespace()
        .get_by_str("__annotations__", vm.heap, vm.interns)
    {
        Some(Value::Ref(id)) => match vm.heap.get(*id) {
            HeapData::Dict(annotations) => Some(annotations),
            _ => None,
        },
        _ => None,
    }
}

/// A stringized annotation as text, or `""` for the non-string annotations
/// Monty never produces (it always stores annotations as source text).
fn annotation_text(annotation: &Value, vm: &VM<'_>) -> String {
    annotation
        .as_either_str(vm.heap)
        .map(|s| s.as_str(vm.interns).to_owned())
        .unwrap_or_default()
}

/// Rejects field lists Monty cannot honour, in CPython's checking order.
///
/// CPython validates defaults per field as it collects them, so a mutable
/// default is reported before the whole-list non-default-after-default check.
fn validate_fields(vm: &mut VM<'_>, fields: &[Value]) -> RunResult<()> {
    for field_value in fields {
        // Read out first: hashing a default needs the heap mutably.
        let Some((name, annotation_text, default)) = read_field(field_value, vm) else {
            continue;
        };
        defer_drop!(default, vm);
        let name = vm.interns.get_str(name).to_owned();
        if is_initvar(&annotation_text) {
            return Err(ExcType::not_implemented(format!(
                "dataclass() does not yet support InitVar (field {name}), which would become an ordinary field"
            ))
            .into());
        }
        if let Some(default) = default {
            // CPython's rule is hashability, not a list/dict/set type check, so
            // a class with `__hash__ = None` is rejected the same way. A factory
            // is exempt: it is the sanctioned way to have a mutable default.
            if default.py_hash(vm)?.is_none() {
                let ty = default.py_type_name(vm);
                return Err(ExcType::value_error(format!(
                    "mutable default <class '{ty}'> for field {name} is not allowed: use default_factory"
                )));
            }
        }
    }
    // CPython rejects the class outright rather than failing at construction.
    if let Some((prev, field)) = first_non_default_after_default(fields, vm) {
        let (prev, field) = (vm.interns.get_str(prev), vm.interns.get_str(field));
        return Err(ExcType::type_error(format!(
            "non-default argument '{field}' follows default argument '{prev}'"
        )));
    }
    Ok(())
}

/// A collected field's name, annotation text, and a **cloned** default — the
/// three things validation needs, read before it takes the heap mutably.
fn read_field(field: &Value, vm: &VM<'_>) -> Option<(StringId, String, Option<Value>)> {
    let Value::Ref(id) = field else { return None };
    let field = field_at_id(vm.heap, *id)?;
    let annotation = field.annotation().map_or_else(String::new, |a| annotation_text(a, vm));
    Some((
        field.name().expect("collection adopts every field"),
        annotation,
        field.default().map(|d| d.clone_with_heap(vm.heap)),
    ))
}

/// The first `(defaulted, non_defaulted)` field pair that would produce an
/// invalid `__init__` signature, or `None` when the order is valid.
///
/// A `default_factory` counts as a default, as it does in CPython's generated
/// signature.
fn first_non_default_after_default(fields: &[Value], vm: &VM<'_>) -> Option<(StringId, StringId)> {
    let mut last_default = None;
    fields.iter().find_map(|field| {
        let Value::Ref(id) = field else { return None };
        let field = field_at_id(vm.heap, *id)?;
        let name = field.name().expect("collection adopts every field");
        match (field.has_default(), last_default) {
            (true, _) => {
                last_default = Some(name);
                None
            }
            (false, Some(prev)) => Some((prev, name)),
            (false, None) => None,
        }
    })
}

/// Whether a stringized annotation denotes `typing.ClassVar`, so the field is
/// excluded.
///
/// Detection is textual where CPython resolves the annotation through the
/// defining module, so neither the import nor a dotted spelling's module is
/// checked — both divergences are in `limitations/dataclasses.md`.
fn is_classvar(annotation: &str) -> bool {
    annotation_head(annotation, "ClassVar")
}

/// Whether a stringized annotation denotes `dataclasses.InitVar`. Matched the
/// same way as [`is_classvar`], and with the same textual-only caveats.
fn is_initvar(annotation: &str) -> bool {
    annotation_head(annotation, "InitVar")
}

/// Whether a stringized annotation names `name`, bare, subscripted, or
/// dotted (`typing.ClassVar[int]`), ignoring surrounding whitespace and quotes.
///
/// Quotes must be stripped because a quoted annotation (`x: "ClassVar[int]"`)
/// is stringized with its quotes intact. The subscript is split off before the
/// qualifier check so a dotted type argument (`ClassVar[a.b]`) still matches.
fn annotation_head(annotation: &str, name: &str) -> bool {
    let s = annotation.trim().trim_matches(|c| c == '\'' || c == '"').trim();
    let head = s.split_once('[').map_or(s, |(head, _)| head).trim_end();
    head.rsplit('.').next() == Some(name)
}

/// Whether `class_id` names a dataclass: CPython's `hasattr(cls,
/// '__dataclass_fields__')`, whatever the attribute now holds.
pub(crate) fn is_dataclass_class(class_id: HeapId, vm: &VM<'_>) -> bool {
    let name: &'static str = StaticStrings::DataclassFields.into();
    class_defines(class_id, name, vm)
}

/// `is_dataclass(obj)` — true when `obj` is a dataclass **class** or an
/// **instance** of one (matching CPython, which accepts both).
fn is_dataclass(vm: &mut VM<'_>, args: ArgValues) -> RunResult<Value> {
    let arg = args.get_one_arg("is_dataclass", vm.heap)?;
    let result = match &arg {
        Value::Ref(id) => match vm.heap.get(*id) {
            HeapData::Class(_) => is_dataclass_class(*id, vm),
            HeapData::Instance(instance) => is_dataclass_class(instance.class(), vm),
            // Host-backed instances and classes carry dataclass-ness as a flag
            // set by the host when the class crossed the wire.
            HeapData::HostClass(hc) => host_class_type(vm.heap, hc.class_id()).is_dataclass(),
            HeapData::HostClassType(ty) => ty.is_dataclass(),
            _ => false,
        },
        _ => false,
    };
    arg.drop_with(vm);
    Ok(Value::Bool(result))
}
